<script setup lang="ts">
import { Button as _AButtonImpl, Divider as _ADividerImpl, Drawer as _ADrawerImpl, Form as _AFormImpl, FormItem as _AFormItemImpl, Input as _AInputImpl, Pagination as _APaginationImpl, Select as _ASelectImpl, Space as _ASpaceImpl, Switch as _ASwitchImpl, Table as _ATableImpl, Textarea as _ATextareaImpl } from 'ant-design-vue'
const AButton: any = _AButtonImpl
const ADivider: any = _ADividerImpl
const ADrawer: any = _ADrawerImpl
const AForm: any = _AFormImpl
const AFormItem: any = _AFormItemImpl
const AInput: any = _AInputImpl
const APagination: any = _APaginationImpl
const ASelect: any = _ASelectImpl
const ASpace: any = _ASpaceImpl
const ASwitch: any = _ASwitchImpl
const ATable: any = _ATableImpl
const ATextarea: any = _ATextareaImpl
import { onMounted, reactive, ref } from 'vue'
import { message, Modal } from 'ant-design-vue'
import PageHeader from '../components/PageHeader.vue'
import { apiRequest } from '../api/client'
import { usePagedList } from '../composables/usePagedList'
import { DeleteOutlined, EditOutlined, PlusOutlined } from '@ant-design/icons-vue'
const list=usePagedList('/api/policy/',{name:''});const open=ref(false);const saving=ref(false);const editId=ref('');const scopes=ref<any[]>([]);const plugins=ref<any[]>([])
const initial=()=>({name:'',desc:'',domain_config:{domain_brute:true,domain_brute_type:'big',alt_dns:true,arl_search:true,dns_query_plugin:false},ip_config:{port_scan:true,port_scan_type:'test',service_detection:false,os_detection:false,ssl_cert:false,skip_scan_cdn_ip:true,port_custom:'80,443',host_timeout_type:'default',host_timeout:900,port_parallelism:32,port_min_rate:60,exclude_ports:''},site_config:{site_identify:true,site_capture:false,search_engines:false,site_spider:false,nuclei_scan:false,web_info_hunter:false},file_leak:false,npoc_service_detection:false,poc_names:[] as string[],brute_names:[] as string[],scope_id:''})
const form=reactive(initial())
async function refs(){const [s,p]=await Promise.all([apiRequest<any>('/api/asset_scope/?page=1&size=100'),apiRequest<any>('/api/poc/?page=1&size=100')]);scopes.value=s.items||[];plugins.value=p.items||[]}
function policyData(){return{name:form.name,desc:form.desc,policy:{domain_config:form.domain_config,ip_config:form.ip_config,site_config:form.site_config,file_leak:form.file_leak,npoc_service_detection:form.npoc_service_detection,poc_config:form.poc_names.map(plugin_name=>({plugin_name,enable:true})),brute_config:form.brute_names.map(plugin_name=>({plugin_name,enable:true})),scope_config:{scope_id:form.scope_id}}}}
async function save(){if(!form.name.trim())return message.error('请输入策略名称');if(form.ip_config.port_scan_type==='custom'&&!form.ip_config.port_custom.trim())return message.error('请输入自定义端口');saving.value=true;try{const data=policyData();await apiRequest(editId.value?'/api/policy/edit/':'/api/policy/add/',{method:'POST',body:JSON.stringify(editId.value?{policy_id:editId.value,policy_data:data}:data)});message.success(editId.value?'策略已更新':'策略已创建');open.value=false;await list.search()}catch(e){message.error((e as Error).message)}finally{saving.value=false}}
function create(){editId.value='';Object.assign(form,initial());open.value=true;refs()}
function edit(record:any){editId.value=record._id;const p=record.policy||{};Object.assign(form,initial(),{name:record.name,desc:record.desc||'',domain_config:{...initial().domain_config,...p.domain_config},ip_config:{...initial().ip_config,...p.ip_config},site_config:{...initial().site_config,...p.site_config},file_leak:!!p.file_leak,npoc_service_detection:!!p.npoc_service_detection,poc_names:(p.poc_config||[]).filter((x:any)=>x.enable).map((x:any)=>x.plugin_name),brute_names:(p.brute_config||[]).filter((x:any)=>x.enable).map((x:any)=>x.plugin_name),scope_id:p.scope_config?.scope_id||''});open.value=true;refs()}
function remove(record:any){Modal.confirm({title:`删除策略“${record.name}”？`,okType:'danger',async onOk(){await apiRequest('/api/policy/delete/',{method:'POST',body:JSON.stringify({policy_id:[record._id]})});await list.load()}})}
const switches=[['domain_config.alt_dns','智能 DNS 字典'],['domain_config.arl_search','ARL 历史查询'],['domain_config.dns_query_plugin','DNS 插件'],['ip_config.service_detection','服务识别'],['ip_config.os_detection','操作系统'],['ip_config.ssl_cert','SSL 证书'],['ip_config.skip_scan_cdn_ip','跳过 CDN IP'],['site_config.site_identify','站点识别'],['site_config.site_capture','站点截图'],['site_config.search_engines','搜索引擎'],['site_config.site_spider','站点爬虫'],['site_config.nuclei_scan','Nuclei'],['site_config.web_info_hunter','信息猎手']]
function get(path:string){const [a,b]=path.split('.');return (form as any)[a][b]}function set(path:string,value:boolean){const[a,b]=path.split('.');(form as any)[a][b]=value}
onMounted(()=>{list.load();refs().catch(()=>{})})
</script>
<template><section class="page"><PageHeader eyebrow="CONTROL / POLICY" title="扫描策略" description="集中维护域名、端口、站点、PoC 与资产边界配置；任务和计划任务可直接引用。"><a-button type="primary" @click="create"><PlusOutlined/>新建策略</a-button></PageHeader><div class="data-panel"><div class="query-strip"><a-input v-model:value="list.filters.name" placeholder="策略名称" @press-enter="list.search"/><a-button @click="list.search">筛选</a-button><span><b>{{list.total}}</b> 个策略</span></div><a-table :data-source="list.rows" :loading="list.loading" row-key="_id" :pagination="false" :columns="[{title:'名称',dataIndex:'name'},{title:'说明',dataIndex:'desc'},{title:'关联资产组',key:'scope'},{title:'更新时间',dataIndex:'update_date'},{title:'操作',key:'action',width:120}]"><template #bodyCell="{column,record}"><span v-if="column.key==='scope'">{{record.policy?.scope_config?.scope_id||'—'}}</span><a-space v-if="column.key==='action'"><a @click="edit(record)"><EditOutlined/>编辑</a><a class="danger-link" @click="remove(record)"><DeleteOutlined/></a></a-space></template></a-table><a-pagination :current="list.page" :page-size="list.size" :total="list.total" @change="list.changePage"/></div><a-drawer v-model:open="open" :title="editId?'编辑扫描策略':'新建扫描策略'" width="min(760px,96vw)"><a-form layout="vertical" @finish="save"><div class="form-grid"><a-form-item label="名称" required><a-input v-model:value="form.name"/></a-form-item><a-form-item label="关联资产组"><a-select v-model:value="form.scope_id" allow-clear :options="scopes.map(x=>({value:x._id,label:x.name}))"/></a-form-item></div><a-form-item label="说明"><a-textarea v-model:value="form.desc" :rows="2"/></a-form-item><a-divider>核心能力</a-divider><div class="switch-grid"><label><a-switch v-model:checked="form.domain_config.domain_brute"/>域名爆破</label><label><a-switch v-model:checked="form.ip_config.port_scan"/>端口扫描</label><label><a-switch v-model:checked="form.file_leak"/>文件泄漏</label><label><a-switch v-model:checked="form.npoc_service_detection"/>NPoC 服务识别</label><label v-for="([path,label]) in switches" :key="path"><a-switch :checked="get(path)" @change="(v:boolean)=>set(path,v)"/>{{label}}</label></div><div class="form-grid"><a-form-item label="域名字典"><a-select v-model:value="form.domain_config.domain_brute_type" :options="['test','big'].map(value=>({value,label:value}))"/></a-form-item><a-form-item label="端口范围"><a-select v-model:value="form.ip_config.port_scan_type" :options="['test','top100','top1000','all','custom'].map(value=>({value,label:value}))"/></a-form-item><a-form-item v-if="form.ip_config.port_scan_type==='custom'" label="自定义端口"><a-input v-model:value="form.ip_config.port_custom"/></a-form-item><a-form-item label="排除端口"><a-input v-model:value="form.ip_config.exclude_ports"/></a-form-item></div><a-divider>插件</a-divider><a-form-item label="PoC 插件"><a-select v-model:value="form.poc_names" mode="multiple" option-filter-prop="label" :options="plugins.filter(x=>x.plugin_type==='poc').map(x=>({value:x.plugin_name,label:`${x.app_name} / ${x.vul_name}`}))"/></a-form-item><a-form-item label="爆破插件"><a-select v-model:value="form.brute_names" mode="multiple" option-filter-prop="label" :options="plugins.filter(x=>x.plugin_type==='brute').map(x=>({value:x.plugin_name,label:`${x.app_name} / ${x.vul_name}`}))"/></a-form-item><div class="drawer-actions"><a-button @click="open=false">取消</a-button><a-button type="primary" html-type="submit" :loading="saving">保存策略</a-button></div></a-form></a-drawer></section></template>
